{"query":"
    query getVariants($ids: [ID!]!, $country: CountryCode!) {
      nodes(ids: $ids) {
        id
        ... on ProductVariant {
          title
          displayName
          inventoryQuantity
          inventoryItem {
            tracked
          }
          media(first: 5) {
            nodes {
              id
              mediaContentType
              status
              preview {
                image {
                  url
                }
              }
            }
          }
          product {
            id: legacyResourceId
            title
            handle
            media: featuredMedia {
              preview {
                image {
                  url
                }
              }
            }
            variantsCount {
              count
              precision
            }
          }
          contextualPricing(context: {country: $country}) {
            price {
              amount
              currencyCode
            }
          }
        }
      }
    }
  ","variables":{"ids":["gid://shopify/ProductVariant/46619238826139","gid://shopify/ProductVariant/46619238301851","gid://shopify/ProductVariant/46619236794523"],"country":"VN"}}

